use sqlparser::dialect::{GenericDialect, MySqlDialect};
use sqlparser::parser::Parser;
use sqlparser::tokenizer::{Location, Span, Token, TokenWithSpan, Tokenizer};

fn main() {
    let m = MySqlDialect {};
    // MySQL: EOF after executable comment, empty hint
    let e = Parser::new(&m).try_with_sql("SELECT 1 + /*!*/").unwrap().parse_statements().unwrap_err();
    println!("5: {e}");
    // MySQL: EOF after versioned executable comment
    let e = Parser::new(&m).try_with_sql("SELECT 1 + /*!50110 2 */").unwrap().parse_statements().unwrap_err();
    println!("6: {e}");
    // MySQL: EOF right after executable comment w/o trailing space
    let e = Parser::new(&m).try_with_sql("SELECT 1 +/*!*/").unwrap().parse_statements().unwrap_err();
    println!("7: {e}");
    let d = GenericDialect {};
    // missing rparen
    println!("8: {}", Parser::parse_sql(&d, "SELECT (1").unwrap_err());
    // missing keyword
    println!("9: {}", Parser::parse_sql(&d, "SELECT * FROM").unwrap_err());
    // caller-provided tokens with explicit EOF at end
    let toks = vec![
        TokenWithSpan::at(Token::make_keyword("SELECT"), Location::new(1, 1), Location::new(1, 7)),
        TokenWithSpan::at(Token::EOF, Location::new(3, 5), Location::new(3, 5)),
    ];
    let p = Parser::new(&d).with_tokens_with_locations(toks);
    println!("10: {:?}", p.peek_token());
    // caller-provided tokens, trailing whitespace participates
    let toks = vec![
        TokenWithSpan::at(Token::make_keyword("SELECT"), Location::new(1, 1), Location::new(1, 7)),
        TokenWithSpan::at(Token::Whitespace(sqlparser::tokenizer::Whitespace::Space), Location::new(1, 7), Location::new(1, 8)),
    ];
    let p = Parser::new(&d).with_tokens_with_locations(toks);
    println!("11: {:?}", p.peek_token());
    // with_tokens: no locations => empty span
    let p = Parser::new(&d).with_tokens(vec![Token::make_keyword("SELECT")]);
    println!("12: {:?}", p.peek_token());
    // empty token list => empty span
    let p = Parser::new(&d).with_tokens_with_locations(vec![]);
    println!("13: {:?}", p.peek_token());
    // tokenizer token count/content unchanged
    let t1 = Tokenizer::new(&d, "SELECT 1 ").tokenize_with_location().unwrap();
    println!("14: {} tokens, last={:?}", t1.len(), t1.last());
    // repeated reads / backup stability
    let mut p = Parser::new(&d).try_with_sql("SELECT -").unwrap();
    let a = p.next_token(); let b = p.next_token(); let e1 = p.next_token();
    let e2 = p.next_token();
    p.prev_token();
    let e3 = p.next_token();
    println!("15: {:?} {:?} {:?} {:?} {:?}", a.token, b.token, e1, e2, e3);
    // reset with new input
    let p = p.with_tokens_with_locations(Tokenizer::new(&d, "SELECT 1 +   ").tokenize_with_location().unwrap());
    println!("16: {:?}", p.peek_token_no_skip());
    let _ = Span::empty();
}
